<?php defined( 'ABSPATH' ) || exit; get_header(); ?>
<?php while ( have_posts() ) : the_post(); bsw_heading( 'Start a conversation' ); ?>
<section class="section"><div class="container contact-grid">
    <div class="contact-details"><div class="entry-content"><?php the_content(); ?></div><div class="contact-card"><p class="eyebrow"><?php echo esc_html( bsw_t( 'Call us' ) ); ?></p><a class="contact-phone" href="tel:<?php echo esc_attr( bsw_contact( 'phone_link' ) ); ?>"><?php echo esc_html( bsw_contact( 'phone' ) ); ?></a></div><div class="contact-card"><p class="eyebrow"><?php echo esc_html( bsw_t( 'Email us' ) ); ?></p><a href="mailto:<?php echo esc_attr( bsw_contact( 'email' ) ); ?>"><?php echo esc_html( bsw_contact( 'email' ) ); ?></a></div><div class="contact-card"><p class="eyebrow"><?php echo esc_html( bsw_t( 'Find us' ) ); ?></p><address><?php echo nl2br( esc_html( bsw_contact( 'address' ) ) ); ?></address><?php if ( bsw_contact( 'area' ) !== bsw_contact( 'address' ) ) : ?><p><?php echo esc_html( bsw_contact( 'area' ) ); ?></p><?php endif; ?><a class="text-link" href="<?php echo esc_url( 'https://www.google.com/maps/search/?api=1&query=' . rawurlencode( bsw_contact( 'address' ) ) ); ?>" target="_blank" rel="noopener noreferrer"><?php echo esc_html( bsw_t( 'Open in maps' ) ); ?> <span class="screen-reader-text"><?php echo esc_html( bsw_t( '(opens in a new tab)' ) ); ?></span><?php echo bsw_icon(); ?></a></div></div>
    <div class="contact-form" id="enquiry-form"><p class="eyebrow"><?php echo esc_html( bsw_t( 'Tell us about your project' ) ); ?></p><h2><?php echo esc_html( bsw_t( 'Request a quote.' ) ); ?></h2><p><?php echo esc_html( bsw_t( 'Share a few details and we\'ll get back to you.' ) ); ?></p><?php if ( shortcode_exists( 'contact-form-7' ) ) { echo do_shortcode( '[contact-form-7 id="' . absint( bsw_translated_post_id( (int) get_option( 'bsw_contact_form_id', 70 ) ) ) . '"]' ); } else { ?><p><?php echo esc_html( bsw_t( 'Please email' ) ); ?> <a href="mailto:<?php echo esc_attr( bsw_contact( 'email' ) ); ?>"><?php echo esc_html( bsw_contact( 'email' ) ); ?></a> <?php echo esc_html( bsw_t( 'or call' ) ); ?> <?php echo esc_html( bsw_contact( 'phone' ) ); ?> <?php echo esc_html( bsw_t( 'to discuss your project.' ) ); ?></p><?php } ?></div>
</div></section>
<?php endwhile; get_footer(); ?>
